"""Ilustrações SVG originais para o catálogo sintético do MVP."""
from pathlib import Path
import random
random.seed(27)
out = Path(__file__).resolve().parents[1] / 'apps/web/public/products'
out.mkdir(parents=True, exist_ok=True)
defs = '''<defs><radialGradient id="bg"><stop stop-color="#faf4e9"/><stop offset="1" stop-color="#eee1d4"/></radialGradient><radialGradient id="corn"><stop stop-color="#f7e0a3"/><stop offset=".65" stop-color="#d5a358"/><stop offset="1" stop-color="#ac7139"/></radialGradient><radialGradient id="cookie"><stop stop-color="#e5b67a"/><stop offset=".75" stop-color="#c5935a"/><stop offset="1" stop-color="#a36d3f"/></radialGradient><linearGradient id="bag" x2="1" y2="1"><stop stop-color="#fffbef" stop-opacity=".75"/><stop offset=".5" stop-color="#fff9e7" stop-opacity=".15"/><stop offset="1" stop-color="#d7c4ab" stop-opacity=".5"/></linearGradient><linearGradient id="pink"><stop stop-color="#deb8bd"/><stop offset="1" stop-color="#b5828c"/></linearGradient><filter id="shadow" x="-40%" y="-40%" width="180%" height="200%"><feDropShadow dx="0" dy="12" stdDeviation="11" flood-color="#5f3523" flood-opacity=".15"/></filter><g id="kernel"><path d="M-9 4C-17 1-16-8-9-10C-9-18 3-19 5-11C15-14 21-3 13 2C19 10 9 17 3 11C-5 18-14 13-9 4Z" fill="url(#corn)" stroke="#c2934f" stroke-width=".4"/><path d="M-6-4Q0-10 7-2" fill="none" stroke="#f9eac6" stroke-width="2" opacity=".8"/></g></defs>'''
def wrap(content, bg='#f1e7dc', size='0 0 500 440'):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{size}" role="img">{defs}<rect width="600" height="600" fill="{bg}"/>{content}</svg>'
def bag(x,y,s=1,label='PIPOCA',flavor='GOURMET',pink=False):
    kernels=''.join(f'<use href="#kernel" transform="translate({random.uniform(25,150):.1f} {random.uniform(65,225):.1f}) rotate({random.randint(0,360)}) scale({random.uniform(.65,1.0):.2f})"/>' for _ in range(125))
    return f'''<g transform="translate({x} {y}) scale({s})" filter="url(#shadow)"><path d="M18 34L157 34L175 253Q88 268 0 253Z" fill="#e9cd92"/>{kernels}<path d="M18 34L157 34L175 253Q88 268 0 253Z" fill="url(#bag)" stroke="#fffaf1" stroke-width="2"/><path d="M15 31Q87 19 160 31L157 43L18 43Z" fill="#eee1c6" stroke="#e4d2ae"/><path d="M24 46L12 248M148 46L163 248" fill="none" stroke="white" stroke-opacity=".45" stroke-width="3"/><path d="M18 32L160 32" stroke="#b89161" stroke-width="2"/><rect x="25" y="122" width="122" height="77" rx="2" fill="{'#e9c6cc' if pink else '#fcf6e7'}"/><rect x="30" y="127" width="112" height="67" rx="1" fill="none" stroke="#b99572" stroke-width=".6"/><text x="86" y="143" text-anchor="middle" font-family="Georgia" font-size="8" fill="#9c6b59">A MOÇA DA PIPOCA</text><path d="M75 152q-3-7 2-7q4-5 7 0q8-4 8 4q5 6-3 8h-13q-7 0-4-5" fill="none" stroke="#aa6d73" stroke-width="1.1"/><text x="86" y="175" text-anchor="middle" font-family="Georgia" font-size="17" letter-spacing="2" fill="#9c6671">{label}</text><text x="86" y="187" text-anchor="middle" font-family="Arial" font-size="5" letter-spacing="2" fill="#ac8850">{flavor}</text><path d="M86 26C47 0 59-8 83 12C100-15 124-3 87 26" fill="none" stroke="#bc7d89" stroke-width="9"/><path d="M87 21L74 60M88 22L106 59" stroke="#c38a92" stroke-width="10"/></g>'''
cornbg='<ellipse cx="250" cy="368" rx="169" ry="22" fill="#cfb89d" opacity=".23"/><path d="M30 105Q70 85 105 96M409 340q34 13 64-2" stroke="#e4cdb7" stroke-width="1" fill="none"/>'
loose=''.join(f'<use href="#kernel" transform="translate({x} {y}) rotate({r}) scale(.6)"/>' for x,y,r in [(87,361,25),(122,387,78),(368,370,-24),(405,358,85),(348,396,12)])
(out/'pipoca-caramelo.svg').write_text(wrap(cornbg+bag(155,65,1.1)+loose),encoding='utf8')
cookie_svg='<ellipse cx="250" cy="348" rx="172" ry="33" fill="#fffaf2" stroke="#e1cebb" stroke-width="4" filter="url(#shadow)"/><ellipse cx="250" cy="338" rx="149" ry="25" fill="#ecded1"/>'
for x,y,r,s in [(204,313,-12,1.1),(293,295,15,1),(235,242,-5,1.08)]:
    chips=''.join(f'<path d="M{random.randint(-56,53)} {random.randint(-45,35)}l9-3 6 8-10 5Z" fill="{random.choice(["#704530","#5a382c","#855039"])}" opacity=".9"/>' for _ in range(21))
    specks=''.join(f'<circle cx="{random.uniform(-57,57)}" cy="{random.uniform(-35,35)}" r="{random.uniform(.6,1.6)}" fill="#a87141" opacity=".6"/>' for _ in range(65))
    cookie_svg+=f'<g transform="translate({x} {y}) rotate({r}) scale({s})" filter="url(#shadow)"><ellipse cy="9" rx="83" ry="57" fill="#a56c3b"/><ellipse rx="83" ry="54" fill="url(#cookie)" stroke="#c18b4d" stroke-width="1"/>{specks}{chips}</g>'
cookie_svg+='<path d="M358 128q35 18 24 58M365 130q-17 20 5 57" fill="none" stroke="#b9a077" stroke-width="1.3"/><path d="M377 139q-17-24-23-12q3 10 23 12M380 158q24-17 27-5q-8 9-27 5M382 177q-14-26-22-13q2 10 22 13" fill="#c8b990" opacity=".7"/>'
(out/'cookies.svg').write_text(wrap(cookie_svg,'#eee4d9'),encoding='utf8')
gift='<ellipse cx="260" cy="370" rx="176" ry="23" fill="#b3978d" opacity=".14"/>'
gift+=bag(180,72,.73,'CARINHO','FEITO À MÃO',True)+bag(290,107,.62,'DOÇURA','COM AMOR')
gift+='''<g filter="url(#shadow)"><path d="M77 216L291 206L340 246L127 258Z" fill="#eccdd1"/><path d="M127 258L340 246L329 363L128 379Z" fill="url(#pink)"/><path d="M77 216L127 258L128 379L84 333Z" fill="#b88891"/><path d="M70 212L290 199L345 243L125 260Z" fill="#e4bec5"/><path d="M125 260L345 243L344 257L125 276Z" fill="#d7a7b2"/><path d="M70 212L125 260L125 276L71 227Z" fill="#c18f9d"/><path d="M174 207L218 205L269 250L224 254Z" fill="#faf0dd"/><path d="M224 254L269 250L265 369L222 372Z" fill="#f3e4cc"/><path d="M231 242C154 222 145 173 180 180C204 184 226 225 231 242Z" fill="#f4e5ce" stroke="#d5c3a9"/><path d="M231 242C270 175 307 194 293 219C282 235 245 242 231 242Z" fill="#fff5e4" stroke="#d5c3a9"/><path d="M230 242L205 298L229 291L237 304L249 244" fill="#f5e6cb"/><rect x="151" y="294" width="47" height="43" fill="#fcf5e5" transform="rotate(-8 151 294)"/><text x="171" y="311" text-anchor="middle" font-family="Georgia" font-size="5.5" fill="#a16e77">um doce</text><text x="171" y="320" text-anchor="middle" font-family="Georgia" font-size="6.5" fill="#a16e77">carinho.</text><path d="M171 328q-9-8-6-10q4-4 7 1q5-4 7 0q1 4-8 9" fill="none" stroke="#bc8895" stroke-width=".7"/></g>'''
(out/'kit-presente.svg').write_text(wrap(gift,'#f1e1e1'),encoding='utf8')
hero='<ellipse cx="285" cy="458" rx="207" ry="33" fill="#b59b82" opacity=".13"/>'
hero+=bag(240,55,1.2)+f'<g transform="translate(-15 173) scale(.83)">{gift}</g>'+bag(78,231,.75,'DOÇURA','ARTESANAL',True)
hero+=''.join(f'<use href="#kernel" transform="translate({x} {y}) rotate({r}) scale(.6)"/>' for x,y,r in [(112,485,17),(154,496,75),(434,470,87),(456,452,-15),(210,485,-12)])
hero+='<path d="M468 142l4 10 11 1-9 7 3 11-9-6-10 6 3-11-9-7 11-1Z" fill="none" stroke="#bfa079" stroke-width="1"/><path d="M75 165l2 7 8 1-6 5 2 8-7-5-7 5 2-8-6-5 8-1Z" fill="none" stroke="#c6a889"/>'
(out/'hero.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 540 550">{defs}{hero}</svg>',encoding='utf8')
print('4 ilustrações SVG locais criadas.')
